                                </div>

                                <!-- Title -->
                                <h3 class="font-black text-base sm:text-lg text-slate-900 tracking-wider uppercase mt-4">
                                    KORIDOR I • UTARA
                                </h3>
                                <div class="text-[11px] font-bold text-[#3B4D3B] tracking-wider uppercase mt-0.5">
                                    Episentrum Industri &amp; Pesisir
                                </div>

                                <!-- Description -->
